        let weight = max(filterRadius + 1.0 - absOffset.x, 0.0) * max(filterRadius + 1.0 - absOffset.y, 0.0);
        lit += shadowCompareAt(cascade, shadowUV + offset, refDepth, texel) * weight;
        weightSum += weight;
