    let glow = pow(max(0.0, cosA), sky.params.z) * sky.params.w;

    // Horizon haze: brighten the horizon band in the direction of the sun.
    let horizonBand = 1.0 - smoothstep(0.0, sky.params.x * 2.5, abs(elevation));
